INSERT dbo.TV_CauHinh VALUES (N'he_so_phu_tinh_nho',N'0.4');
INSERT dbo.TV_CauHinh VALUES (N'phi_tuyen',N'{"K": null, "sao_pha": ["Kình Dương", "Đà La", "Hỏa Tinh", "Linh Tinh", "Địa Không", "Địa Kiếp", "Hóa Kỵ", "Thiên Hình"], "vung": "ban_cung", "ghi_chu": "Không còn phi tuyến trong công thức điểm (v3 thay bằng CAP tổng sát −30). Mục này chỉ còn ''trong_so'' (trọng số vị trí cho điểm CÂU của sát tinh bản cung/xung/tam hợp) và ''sao_pha''.", "trong_so": {"ban_cung": 1.0, "xung": 0.5, "tam_hop": 0.25}}');
INSERT dbo.TV_CauHinh VALUES (N'he_so_sao_luu',N'{"Lưu": 0.6, "ĐH": 0.8, "ghi_chu": "Sao lưu niên / Tứ Hóa đại hạn chồng lên lá số gốc: lấy điểm phụ tinh gốc × hệ số này."}');
INSERT dbo.TV_CauHinh VALUES (N'than_cu',N'{"Mệnh": "Thân cư Mệnh: tính cách trước sau như một, tự lập, đời người chịu ảnh hưởng chính từ bản thân.", "Phúc Đức": "Thân cư Phúc: hậu vận dựa vào phúc đức họ hàng, coi trọng đời sống tinh thần, hưởng thụ.", "Quan Lộc": "Thân cư Quan: sau ~30 tuổi lấy sự nghiệp làm trọng, dồn sức cho công việc.", "Thiên Di": "Thân cư Di: hay đi xa, thay đổi chỗ ở/việc làm; thành bại gắn với môi trường bên ngoài.", "Tài Bạch": "Thân cư Tài: coi trọng tiền bạc, hậu vận xoay quanh chuyện kiếm và giữ tiền.", "Phu Thê": "Thân cư Phu Thê: hậu vận chịu ảnh hưởng lớn từ vợ/chồng; hôn nhân là trục của đời sống.", "nguon": "Kiến thức phổ thông tử vi VN, viết lại bằng lời mình (draft_ai_tong_hop)."}');
INSERT dbo.TV_CauHinh VALUES (N'chu_de',N'{"Tính cách": {"cung": {"Mệnh": 1.0}, "linh_vuc": ["tinh_cach", "danh"], "gian_tiep": {"Thiên Di": "môi trường bên ngoài cạnh tranh, bôn ba; dễ nóng vội, quyết liệt khi ra xã hội"}}, "Sự nghiệp": {"cung": {"Quan Lộc": 1.0}, "linh_vuc": ["su_nghiep", "quyen", "danh", "hoc", "quy_nhan"], "gian_tiep": {"Tài Bạch": "chuyện tiền bạc/hao tán tác động gián tiếp tới công việc", "Mệnh": "tâm thế và quyết định cá nhân tác động gián tiếp tới công việc", "Thiên Di": "môi trường bên ngoài, quan hệ xã hội tác động gián tiếp tới công việc"}}, "Tài chính": {"cung": {"Tài Bạch": 1.0}, "linh_vuc": ["tai", "hao"], "gian_tiep": {"Phúc Đức": "bất an tinh thần, lo nghĩ tác động gián tiếp tới tiền bạc (sao nằm ở cung Phúc Đức, không nằm tại cung Tài)", "Mệnh": "tâm thế và quyết định cá nhân tác động gián tiếp tới tiền bạc", "Thiên Di": "biến động bên ngoài tác động gián tiếp tới tiền bạc"}}, "Tình cảm – hôn nhân": {"cung": {"Phu Thê": 1.0}, "linh_vuc": ["tinh_cam", "co_doc"], "gian_tiep": {"Phúc Đức": "bất an tinh thần, lo nghĩ khiến đời sống tình cảm nhiều sóng", "Thiên Di": "môi trường bên ngoài, quan hệ xã hội tác động gián tiếp tới chuyện tình cảm"}}, "Sức khỏe": {"cung": {"Tật Ách": 1.0}, "linh_vuc": ["suc_khoe", "tai_nan", "an_khang", "giai_ach"], "gian_tiep": {"Thiên Di": "đề phòng tai nạn, va chạm khi di chuyển/ngoài đường", "Mệnh": "thể trạng và tinh thần chung ảnh hưởng tới sức khỏe"}}, "Gia đình": {"cung": {"Phụ Mẫu": 0.5, "Tử Tức": 0.5, "Huynh Đệ": 0.5}, "linh_vuc": [], "ghi_chu": "Gia đình = Phụ Mẫu + Tử Tức + Huynh Đệ, luôn tách tiểu mục (Cha mẹ / Con cái / Anh em); mỗi câu mang nhãn tiểu mục = cung nguồn. Không đổi theo lá số.", "tieu_muc": {"Phụ Mẫu": "Cha mẹ", "Tử Tức": "Con cái", "Huynh Đệ": "Anh em"}}, "ghi_chu": "Mỗi chủ đề lấy ĐÚNG cung chủ (Gia đình = Phụ Mẫu + Tử Tức + Huynh Đệ, tách tiểu mục); sao ở xung chiếu/tam hợp đã được chấm trong tam phương của cung chủ và chỉ được nêu kèm nguồn (''gian_tiep'': sao từ cung X xung/hội chiếu cung chủ → hệ quả gián tiếp)."}');
INSERT dbo.TV_CauHinh VALUES (N'han',N'{"tu_hoa_dai_han": true, "ghi_chu": "Tứ Hóa đại hạn (can cung đại hạn) là kỹ thuật Bắc phái/Tứ Hóa phái; phái Thái Thứ Lang không dùng. Tắt = chỉ xét sao gốc + sao lưu.", "tieu_han": "Khởi theo tam hợp chi năm sinh (Thân Tý Thìn → Tuất, Dần Ngọ Tuất → Thìn, Tỵ Dậu Sửu → Mùi, Hợi Mão Mùi → Sửu), 1 tuổi tại cung khởi, nam thuận nữ nghịch.", "luu_nguyet": "Đẩu Quân năm xem: từ cung Thái Tuế năm xem đếm nghịch tới tháng sinh, rồi thuận tới giờ sinh → tháng Giêng; các tháng sau đi thuận.", "khuyen_nghi": {"Mệnh": {"muc": "bản thân, tinh thần", "nen": "giữ tâm thế bình tĩnh, chăm sóc sức khỏe tinh thần", "tranh": "quyết định lớn lúc nóng nảy hoặc bất ổn tâm lý"}, "Tài Bạch": {"muc": "tiền bạc", "nen": "rà soát kỹ hợp đồng, giữ quỹ dự phòng", "tranh": "đầu tư mạo hiểm, đứng tên/bảo lãnh khoản lớn"}, "Quan Lộc": {"muc": "công việc", "nen": "giữ mồm miệng, làm việc minh bạch, lưu bằng chứng bằng văn bản", "tranh": "thị phi, va chạm, đối đầu nơi làm việc"}, "Phu Thê": {"muc": "tình cảm – hôn nhân", "nen": "trao đổi thẳng thắn với người thân thiết", "tranh": "quyết định bốc đồng trong chuyện tình cảm"}, "Tật Ách": {"muc": "sức khỏe", "nen": "khám định kỳ, ngủ nghỉ điều độ", "tranh": "chủ quan với triệu chứng, làm việc quá sức"}, "Thiên Di": {"muc": "đi lại, quan hệ bên ngoài", "nen": "cẩn thận khi di chuyển, giữ gìn đồ đạc", "tranh": "đi xa/đi đêm không cần thiết"}, "Phúc Đức": {"muc": "đời sống tinh thần", "nen": "giữ nếp sinh hoạt cân bằng, bớt lo nghĩ", "tranh": "sa đà ham muốn, chuyện tình cảm rắc rối"}, "Điền Trạch": {"muc": "nhà đất, tài sản", "nen": "kiểm tra kỹ giấy tờ pháp lý", "tranh": "mua bán nhà đất vội vàng"}, "Phụ Mẫu": {"muc": "cha mẹ, cấp trên, giấy tờ", "nen": "quan tâm cha mẹ, kiểm tra kỹ giấy tờ", "tranh": "xung đột với người trên"}, "Tử Tức": {"muc": "con cái", "nen": "dành thời gian gần gũi", "tranh": "áp đặt, nóng nảy"}, "Huynh Đệ": {"muc": "anh chị em, người ngang hàng", "nen": "giữ liên lạc đều đặn", "tranh": "cho vay mượn, hùn hạp với người thân"}, "Nô Bộc": {"muc": "bạn bè, đối tác, cấp dưới", "nen": "chọn kỹ đối tác", "tranh": "tin người, hùn hạp vội vàng"}}, "luu_sat": {"Lưu Kình Dương": "áp lực, sát khí", "Lưu Đà La": "trì trệ, vướng víu", "Lưu Hóa Kỵ": "vướng mắc, thị phi, tâm trạng bất ổn", "Lưu Tang Môn": "buồn lo, mất mát", "Lưu Bạch Hổ": "cạnh tranh, va chạm"}, "luu_cat": ["Lưu Hóa Lộc", "Lưu Hóa Quyền", "Lưu Hóa Khoa", "Lưu Lộc Tồn"], "tan_dung": "khởi sự/chuyển đổi có tính toán, ưu tiên bước đi dài hạn hơn nước đi ngắn hạn rủi ro", "trong_yeu": ["Mệnh", "Tài Bạch", "Quan Lộc", "Phu Thê", "Tật Ách"]}');
INSERT dbo.TV_CauHinh VALUES (N'sat_tinh',N'{"sat": ["Kình Dương", "Đà La", "Hỏa Tinh", "Linh Tinh", "Địa Không", "Địa Kiếp", "Hóa Kỵ"], "ban_sat": ["Thiên Hình", "Thiên Diêu"], "ghi_chu": "Định nghĩa dùng chung cho câu cảnh báo sát tinh: 7 sát tinh + 2 bán-sát. Lưu/ĐH tính theo sao gốc."}');
INSERT dbo.TV_CauHinh VALUES (N'diem_noi_tai',N'{"_ghi_chu": "Điểm /100 là điểm tuyệt đối của công thức diem_v3 (START 50), không phải percentile và không so với lá số khác. Làm tròn bội số 5, kẹp 5–95.", "bac": [[30, "Rất thấp"], [45, "Thấp"], [60, "Trung bình"], [75, "Khá"], [90, "Tốt"], [100, "Rất tốt"]], "nguong_cat_xung_hoi": 5.0, "bac_mota": "≤30 Rất thấp · 31–45 Thấp (dưới trung bình) · 46–60 Trung bình · 61–75 Khá · 76–90 Tốt · ≥91 Rất tốt (spec v3 §4.7). Điểm làm tròn bội 5.", "khop_noi_dung": {"khá_tran": 65, "tb_tran": 60, "ghi_chu": "§4.8: sáng ≥ 2×hung và có chính tinh miếu/vượng (hoặc không có hung mà có chính tinh đắc) → nhãn ≥ khá (65); hung ≥ 2×sáng → nhãn ≤ trung bình (60)."}}');
INSERT dbo.TV_CauHinh VALUES (N'vcd_theo_cung',N'{"Tử Tức": "Tử Tức vô chính diệu: mượn sao cung xung chiếu để luận; thường luận con muộn hoặc ít, chất lượng hơn số lượng. Không tự động là xấu — đánh giá theo sao mượn và phụ tinh (Tả/Hữu/Tấu Thư là cát thì nâng).", "Huynh Đệ": "Huynh Đệ vô chính diệu: mượn sao cung xung chiếu để luận; anh chị em thường ít hoặc không gần gũi. Không tự động là xấu — đánh giá theo sao mượn và phụ tinh.", "Tài Bạch": "Tài Bạch vô chính diệu: nguồn thu thiếu trục chính, nền thu nhập thiếu ổn định; luận theo sao mượn ở cung xung chiếu (cách kiếm tiền) và phụ tinh tại cung.", "Thiên Di": "Thiên Di vô chính diệu: hình ảnh/môi trường bên ngoài thiếu trục chính, dễ thích nghi; luận theo sao mượn ở cung xung chiếu và phụ tinh tại cung."}');
INSERT dbo.TV_CauHinh VALUES (N'he_so_chinh_tinh_chu',N'2.0');
INSERT dbo.TV_CauHinh VALUES (N'vcd_mac_dinh',N'"{cung} vô chính diệu: không có chính tinh tại cung, mượn chính tinh cung xung chiếu (giảm lực) để luận; đánh giá theo sao mượn và phụ tinh, không tự động là xấu."');
INSERT dbo.TV_CauHinh VALUES (N'nhom_cung',N'{"Mệnh": "menh_phuc", "Phúc Đức": "menh_phuc", "Tài Bạch": "tai_dien", "Điền Trạch": "tai_dien", "Quan Lộc": "quan_no", "Nô Bộc": "quan_no", "Phu Thê": "phu", "Tử Tức": "tu", "Phụ Mẫu": "phu_huynh", "Huynh Đệ": "phu_huynh", "Thiên Di": "di_tat", "Tật Ách": "di_tat"}');
INSERT dbo.TV_CauHinh VALUES (N'mau_theo_nhom',N'{"_ghi_chu": "Câu riêng theo NHÓM cung cho phụ tinh chưa có câu riêng ở phu_tinh_tai_cung_chuc.json — tránh dùng một câu generic cho cả 12 cung. Do tác giả (AI) soạn, chưa đối chiếu sách.", "Tang Môn": {"menh_phuc": "Bạn hay buồn lo, đời sống tinh thần dễ có mất mát; nên đề phòng tang sự trong họ.", "tai_dien": "Bạn dễ hao tài vì hiếu hỉ hoặc tang sự và chi phí đột xuất; nên có quỹ dự phòng.", "quan_no": "Công việc và quan hệ với cấp dưới của bạn nhiều lo toan, dễ gặp chuyện buồn phải xử lý.", "phu_huynh": "Người thân của bạn có chuyện buồn; nên lưu ý đau ốm hoặc tang sự trong gia đình.", "di_tat": "Bạn nên đề phòng đau yếu và buồn phiền, nhất là khi ra ngoài.", "phu": "Tình cảm của bạn dễ có chuyện buồn lo và xa cách.", "tu": "Con cái của bạn dễ có chuyện buồn lo và xa cách."}, "Bạch Hổ": {"menh_phuc": "Cá tính bạn quyết liệt; nên đề phòng thương tích và miệng tiếng.", "tai_dien": "Tiền bạc và nhà đất của bạn dễ tranh chấp, và có thể hao vì kiện tụng hoặc tai nạn.", "quan_no": "Bạn dễ gặp cạnh tranh gay gắt, va chạm và thị phi nơi làm việc cũng như trong các mối quan hệ.", "phu_huynh": "Quan hệ của bạn với người thân dễ va chạm; nên đề phòng chuyện tang sự.", "di_tat": "Bạn nên đề phòng tai nạn, thương tích và mổ xẻ.", "phu": "Hôn nhân của bạn dễ có va chạm; nên đề phòng tai nạn và mổ xẻ.", "tu": "Con cái của bạn hay va chạm và đau yếu; nên đề phòng tai nạn và mổ xẻ."}, "Đại Hao": {"menh_phuc": "Bạn dễ hao tán và tiêu xài vượt kế hoạch.", "tai_dien": "Bạn dễ hao tán lớn, tiền ra nhanh hơn tiền vào.", "quan_no": "Bạn dễ hao công sức và tốn kém vì các mối quan hệ, cấp dưới.", "phu_huynh": "Bạn dễ tốn kém vì người thân.", "di_tat": "Bạn dễ hao sức khi ra ngoài hoặc khi đau yếu.", "phu": "Bạn dễ tốn kém cho chuyện tình cảm.", "tu": "Bạn dễ tốn kém cho con cái."}, "Kiếp Sát": {"menh_phuc": "Tính bạn quyết đoán và hơi cứng; nên đề phòng tai nạn và xung đột.", "tai_dien": "Bạn dễ mất của vì bị lừa, bị cướp hoặc tranh chấp.", "quan_no": "Bạn dễ gặp cạnh tranh gay gắt và bị lấn át.", "phu_huynh": "Người thân của bạn dễ xung đột với nhau.", "di_tat": "Bạn nên đề phòng tai nạn và phẫu thuật.", "phu": "Tình cảm của bạn dễ va chạm và chia ly.", "tu": "Con cái của bạn dễ va chạm và xa cách."}}');
INSERT dbo.TV_CauHinh VALUES (N'mien_cung',N'{"tai": ["Mệnh", "Phúc Đức", "Tài Bạch", "Điền Trạch", "Quan Lộc", "Nô Bộc", "Thiên Di", "Huynh Đệ"], "nha_dat": ["Mệnh", "Phúc Đức", "Điền Trạch", "Tài Bạch"], "tinh_cam": ["Mệnh", "Phúc Đức", "Phu Thê"], "con_cai": ["Tử Tức"], "cha_me": ["Phụ Mẫu"], "anh_em": ["Huynh Đệ"], "suc_khoe": ["Mệnh", "Phúc Đức", "Tật Ách"], "nguoi_nha": ["Mệnh", "Phúc Đức", "Điền Trạch", "Phụ Mẫu", "Phu Thê", "Tử Tức", "Huynh Đệ"], "ca_nhan": ["Mệnh", "Phúc Đức", "Quan Lộc", "Nô Bộc", "Thiên Di", "Tài Bạch", "Phụ Mẫu", "Tử Tức"]}');
INSERT dbo.TV_CauHinh VALUES (N'mien_tu_khoa',N'{"_ghi_chu": "Từ khóa nhận diện lĩnh vực của một mệnh đề. Mệnh đề (tách theo ''; '' hoặc ''. '') nói về lĩnh vực nào thì CHỈ được nối vào cung thuộc lĩnh vực đó (mien_cung); sai cung thì bỏ mệnh đề. Áp cho câu tổ hợp Tứ Hóa và câu fallback ý nghĩa chung của sao — không áp cho câu riêng theo (sao × cung).", "tai": "tiền|tài lộc|tài sản|hao tài|hao tán|giàu|kiếm|của cải|nợ|kinh tế|vật chất|hùn vốn|tài tích lũy", "nha_dat": "nhà đất|nhà cửa|đất đai", "tinh_cam": "hôn nhân|vợ|chồng|tình cảm|đa tình|cưới", "con_cai": "con cái|chậm con|muộn con|ít con", "cha_me": "cha mẹ", "anh_em": "anh em(?! họ)|anh chị", "suc_khoe": "bệnh|sức khỏe|máu huyết|lưu ý mắt", "nguoi_nha": "người nam trong nhà|người nữ trong nhà", "ca_nhan": "quyền lực|có quyền|nắm quyền|quyền uy|tiếng nói|trọng lượng|tham vọng|giao tế|danh vọng|uy tín|đổi mới|cải cách|mưu lược|tham mưu|làm thầy|danh thanh cao|thi cử|học hành|văn bằng|tài nghệ|danh nhờ|hào phóng|được tôn trọng|danh có quyền"}');
INSERT dbo.TV_CauHinh VALUES (N'phan_cuc_rieng',N'{"_ghi_chu": "Hệ số nhân điểm cho cặp ''sao|cung'' khi câu riêng của cặp đó là TRUNG TÍNH/HỖN HỢP hoặc ngược dấu với điểm chung của sao (VD Lộc Tồn ở Huynh Đệ: ''anh em ít''). 0 = trung tính (vẫn hiện ở tab Từng cung, không vào điểm sáng/lưu ý); hệ số luôn trong [0, 1] để giữ tính đơn điệu (thêm cát tinh không làm điểm giảm). Do tác giả (AI) rà bảng phu_tinh_tai_cung_chuc.json, chưa đối chiếu sách.", "Lộc Tồn|Huynh Đệ": 0, "Lộc Tồn|Tử Tức": 0, "Lộc Tồn|Nô Bộc": 0, "Lộc Tồn|Phu Thê": 0, "Thiên Mã|Phụ Mẫu": 0, "Thiên Mã|Phúc Đức": 0, "Thiên Mã|Điền Trạch": 0, "Thiên Mã|Tử Tức": 0, "Thiên Mã|Phu Thê": 0, "Thiên Mã|Huynh Đệ": 0, "Thiên Mã|Tật Ách": 0, "Hóa Quyền|Tử Tức": 0, "Hóa Quyền|Huynh Đệ": 0, "Hóa Quyền|Phu Thê": 0.5, "Hóa Quyền|Phúc Đức": 0.5, "Hóa Quyền|Tật Ách": 0.5, "Văn Xương|Tật Ách": 0}');
INSERT dbo.TV_CauHinh VALUES (N'cach_cuc_giam_dan',N'{"he_so": [1.0, 0.6, 0.35, 0.2], "ghi_chu": "Nhiều cách cục cùng dấu trên một cung thường dùng chung các sao (VD Xương Khúc vừa cho ''Văn Quế Văn Hoa'' vừa cho ''Dương Lương Xương Lộc''); cộng tuyến tính là đếm đôi. Cách mạnh nhất tính đủ, các cách sau nhân dần hệ số này (tốt và xấu tính riêng)."}');
INSERT dbo.TV_CauHinh VALUES (N'diem_cham_rieng',N'{"_ghi_chu": "Bàng tinh cố định theo vòng (Tang Môn, Bạch Hổ, Đại Hao, Kiếp Sát) có mặt ở MỌI lá số nên nếu trừ ngang lục sát (-2) thì điểm cung bị nhiễu theo năm sinh. Điểm CHẤM = -1; câu luận vẫn hiện như cũ.", "Tang Môn": -1, "Bạch Hổ": -1, "Đại Hao": -1, "Kiếp Sát": -1}');
INSERT dbo.TV_CauHinh VALUES (N'diem_v3',N'{"_ghi_chu": "Công thức điểm một cung theo spec scoring v3 §4. CẤU TRÚC (thứ tự bước, dấu, nén Tuần/Triệt, sàn) là bắt buộc; mọi CON SỐ là giá trị khởi điểm để tune (xem hieu_chinh.py để xem phân bố trên lá số ngẫu nhiên).", "start": 50, "base": {"M": 12, "V": 9, "Đ": 6, "B": 2, "H": -3, "khong_ro": 2}, "base_cap": [-6, 20], "cat": {"ban_cung": 4, "xung": 2.5, "tam_hop": 2}, "cat_hoa_nhan": 1.5, "cat_ham_he_so": 0.3, "cat_cap": 25, "sat": {"ban_cung": -5, "xung": -3, "tam_hop": -2}, "sat_ban_sat_he_so": 0.5, "sat_ham": 1.3, "sat_dac": 0.5, "sat_cap": -30, "nen": {"Triệt": 0.6, "Tuần": 0.8}, "san": {"n2": 65, "n1": 55, "tru_triet": 7, "tru_tuan": 4, "ghi_chu": "Spec ghi n≥2 → 62 nhưng sau làm tròn bội 5 thành 60 (nhãn Trung bình) trong khi kỳ vọng ''khá''; đặt 65 để nhãn khớp kỳ vọng."}, "cach_cuc": {"he_so": 2.0, "cap": 8, "ghi_chu": "Điều chỉnh cách cục (đã giảm dần) cộng vào trước khi nén Tuần/Triệt, kẹp ±cap. Không có trong spec v3 — giữ vì docs/06 coi cách cục đè lên luận từng sao."}, "kep": [5, 95], "ghi_chu_sat_dac": "Spec ghi Đắc ×0.7; hạ còn ×0.5 để sát đắc địa (VD Địa Kiếp đắc ở Dần đồng cung Tật Ách) không kéo cung xuống dưới kỳ vọng §16 lá 4 (Sức khỏe ≈ trung bình). Hằng số tune, không phải cấu trúc."}');
