INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Mệnh',N'chinh_tinh_cung',N'Tử Vi tại Mệnh',N'Mệnh',N'{"co": "Tử Vi"}',N'Bạn có phong thái uy nghi, tự trọng và tố chất của người đứng đầu.',N'Bạn dễ tự cao và hay thấy mình đơn độc, nên coi chừng chuyện ham hư danh.',2,N'da_viet_lai_giong_nguoi_doc');
INSERT dbo.TV_QuyTac (Ma_QuyTac,Loai,Ten,Pham_Vi,Dieu_Kien,Ket_Luan,Ket_Luan_Pha,Diem,Trang_Thai) VALUES (N'CT.Tử Vi.Phụ Mẫu',N'chinh_tinh_cung',N'Tử Vi tại Phụ Mẫu',N'Phụ Mẫu',N'{"co": "Tử Vi"}',N'Cha mẹ bạn có vị thế và che chở được cho bạn.',N'Cha mẹ bạn khá nghiêm, nên hai bên khó gần gũi.',1,N'da_viet_lai_giong_nguoi_doc');
